90	function rawRequest(
91	  method: string,
92	  target: string,
93	  headers: readonly [string, string][],
94	  body: Buffer,
95	): Buffer {
96	  const lines = [`${method} ${target} HTTP/1.1`, 'Host: 127.0.0.1'];
97	  for (const [name, value] of headers) {
98	    lines.push(`${name}: ${value}`);
99	  }
100	  lines.push(`Content-Length: ${body.byteLength}`, 'Connection: close', '', '');
101	  return Buffer.concat([Buffer.from(lines.join('\r\n'), 'utf8'), body]);
102	}
