104	function rawExchange(port: number, raw: Buffer): Promise<number> {
105	  return new Promise((resolve, reject) => {
106	    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
107	    const chunks: Buffer[] = [];
108	    socket.on('data', (c: Buffer) => chunks.push(c));
109	    socket.on('end', () => {
110	      const head = Buffer.concat(chunks).toString('latin1');
111	      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
112	      if (m) {
113	        resolve(Number(m[1]));
114	      } else {
115	        reject(new Error(`未收到完整响应状态行：${head.slice(0, 120)}`));
116	      }
117	    });
118	    socket.on('error', reject);
119	    socket.setTimeout(10_000, () => {
120	      socket.destroy();
121	      reject(new Error('原始请求 10s 内未完成（疑似卡住）'));
122	    });
123	  });
124	}
