  ]);
  const requests: { raw: Buffer; online: number }[] = [
    { raw: rawRequest('GET', '/api/seq?a=1&b=%E4%B8%AD', [], Buffer.alloc(0)), online: 200 },
    { raw: rawRequest('POST', '/api/echo', [], invalidBody), online: 201 },
