  assert.equal(report.results[3].response?.body.content, 'not found\n');

  // 正文无损：目标服务记录到的 POST /api/echo 正文与原始字节完全一致
  const targetSnapshot = JSON.parse(
    await httpGetBody(target.port, '/__contractlab/requests'),
