Now the diff function:

```ts
const MISSING = 'missing';

interface BodyDifference {
  readonly pointer: string;
  readonly planned: unknown; // JSON 值或 "missing"
  readonly actual: unknown;
}

function pointerOf(path: readonly string[]): string {
  return path.length === 0 ? '' : `/${path.map(escapePointerSegment).join('/')}`;
}

function diffJsonValues(planned, actual, ignore, path, out): void {
  const pointer = pointerOf(path);
  if (ignore.has(pointer)) return;
  const pt = jsonTypeOf(planned);
  const at = jsonTypeOf(actual);
  if (pt !== at) { out.push({ pointer, planned, actual }); return; }
  if (pt === 'object') {
    const p = planned as Record<string, unknown>;
    const a = actual as Record<string, unknown>;
    for (const key of Object.keys(p)) {
      const childPath = [...path, key];
      if (!Object.prototype.hasOwnProperty.call(a, key)) {
        const childPointer = pointerOf(childPath);
        if (!ignore.has(childPointer)) out.push({ pointer: childPointer, planned: p[key], actual: MISSING });
      } else {
        diffJsonValues(p[key], a[key], ignore, childPath, out);
      }
    }
    for (const key of Object.keys(a)) {
      if (!Object.prototype.hasOwnProperty.call(p, key)) {
        const childPointer = pointerOf([...path, key]);
        if (!ignore.has(childPointer)) out.push({ pointer: childPointer, planned: MISSING, actual: a[key] });
      }
    }
    return;
  }
  if (pt === 'array') {
    const p = planned as unknown[];
    const a = actual as unknown[];
    const n = Math.max(p.length, a.length);
    for (let i = 0; i < n; i += 1) {
      const childPath = [...path, String(i)];
      const childPointer = pointerOf(childPath);
      if (ignore.has(childPointer)) continue;
      if (i >= p.length) out.push({ pointer: childPointer, planned: MISSING, actual: a[i] });
      else if (i >= a.length) out.push({ pointer: childPointer, planned: p[i], actual: MISSING });
      else diffJsonValues(p[i], a[i], ignore, childPath, out);
    }
    return;
  }
  if (planned !== actual) out.push({ pointer, planned, actual });
}
```

Note `planned !== actual` for numbers: `-0 !== 0` is false (they're ===), good. NaN can't appear from JSON.parse.

One subtlety: `Object.keys` on JSON.parse'd object with `__proto__` key — JSON.parse creates own data property, and Object.keys includes it. Accessing `p['__proto__']` on such object returns the own property value (own property shadows prototype). Good. But careful: `p[key]` where key='__proto__' — own property takes precedence. Yes.

Also `jsonTypeOf` returns typeof for scalars: 'string' | 'number' | 'boolean' | 'object'(plain) | 'null' | 'array'. Note: typeof null is 'object' but jsonTypeOf handles null first. Plain objects → 'object'. Good.

