72	// ---------------------------------------------------------------------------
73	// 目标服务：按“方法 + 去查询串路径”路由到预设状态与正文（正文可为任意字节）
74	// ---------------------------------------------------------------------------
75	
76	interface Route {
77	  readonly status: number;
78	  readonly body: string | Buffer;
79	}
80	
81	interface Target {
82	  readonly port: number;
83	  readonly hits: readonly string[];
84	}
85	
86	async function startTarget(t: TestContext, routes: Readonly<Record<string, Route>>): Promise<Target> {
87	  const hits: string[] = [];
88	  const server = http.createServer((req, res) => {
89	    const key = `${String(req.method)} ${String(req.url).split('?')[0]}`;
90	    hits.push(key);
91	    const route = routes[key] ?? { status: 404, body: 'not found' };
92	    req.resume();
93	    req.on('end', () => {
94	      res.writeHead(route.status, { 'Content-Type': 'application/json; charset=utf-8' });
95	      res.end(route.body);
96	    });
97	  });
98	  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
99	  t.after(() => server.close());
100	  const address = server.address();
101	  const port = typeof address === 'object' && address ? address.port : 0;
102	  return { port, hits };
103	}
